import{z as n,x as i,o as B,c as s,q as t,j as r,D as l,d as A,s as o,S as p,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"llama.cpp 走读","description":"","frontmatter":{"title":"llama.cpp 走读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-llamacpp-walkthrough.md","filePath":"llm/fw-llamacpp-walkthrough.md","lastUpdated":1791413859000}'),m={name:"llm/fw-llamacpp-walkthrough.md"};function C(D,E,d,F,h,c){const e=i("Mermaid");return B(),s("div",null,[E[2]||(E[2]=t('<h1 id="llama-cpp-走读" tabindex="-1">llama.cpp 走读 <a class="header-anchor" href="#llama-cpp-走读" aria-label="Permalink to &quot;llama.cpp 走读&quot;">​</a></h1><div class="epigraph"><p>没有引擎计划、没有调度进程，每一步都现场画一张计算图——慢工出细活的前提是图本身足够小。</p><footer>—— 据 ggml 与 llama.cpp 仓库结构、GGUF 规范整理</footer></div><p><a href="/llm/fw-tensorrt-llm-walkthrough">上一课</a>看构建期把内核浇死的路线，llama.cpp 走另一极：不预编译、不依赖 Python，运行时逐步构建计算图。单机本地路径的能力面已写过：量化权重加少依赖的 C/C++ 运行时，见 <a href="/llm/llamacpp">llama.cpp / ggml</a>，权重容器见 <a href="/llm/gguf">GGUF</a>。本课进仓库讲两个库的分工与关键数据结构，以仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用服务端框架的读法进来同样会落空：这里没有请求对象的生命周期管理，没有跨进程消息，连「调度器」都只是一个简单的槽位表。仓库其实是两个库叠放：底下的张量库 ggml 管张量、后端与计算图，上面的 llama 管模型、词表、采样与缓存。迷路的根源是把两层看混——把会话状态当成张量库的事，或把量化当成模型层的转换步骤。走读先钉分工：ggml 是「怎么算」，llama 是「算什么」。</p><p><span class="marginnote">术语翻译：「计算图」就是把一次前向拆成一串算子（嵌入→注意力→前馈→…）画成的有向无环图（DAG），箭头表示「先算谁、把结果给谁」。可以想象成菜谱的工序单：PyTorch 一类框架边跑边记这张单子，llama.cpp 则每一步重新手写工序单、算完就扔。</span></p><h3 id="两库的边界" tabindex="-1">两库的边界 <a class="header-anchor" href="#两库的边界" aria-label="Permalink to &quot;两库的边界&quot;">​</a></h3><p>ggml 侧：张量是带类型与步长的多维数组，量化是张量的<strong>存储类型</strong>而不是转换层，四比特族直接是合法类型；计算图是有向无环的节点图，构建函数逐个压入节点；后端抽象让同一张图落到 CPU、Metal、CUDA 或 Vulkan，跨后端的调度器负责把节点切给各自设备并在接缝处搬数据。llama 侧：模型对象从 GGUF 文件加载权重与超参，会话对象持有缓存与执行状态，批结构把要算的 token、位置、所属序列打包，采样器链把 logits 变成 token。</p><p><span class="marginnote">「量化是存储类型」值得单独翻译：一般框架里，量化像「先解压再使用」的转换步骤；llama.cpp 里 4-bit 权重本身就是一种一等公民的数据类型（如 Q4_K），计算核看到类型直接按 4-bit 的方式算。好比压缩图片不是「用时先解压」，而是显示器原生支持该格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沿一步解码走。输入批里每个 token 带位置与序列归属，会话按它画一张图：嵌入、逐层注意力与前馈、输出头，注意力节点引用当前 KV 缓存。图交给后端调度器，逐节点分派到设备执行；计算完，会话把新 token 的键值写进缓存格子。缓存是走读的关键结构：一排格子记每个位置的有效位与所属序列集合，注意力按位置掩码读取——「这条序列看得见哪些历史」不是靠连续数组，而是靠格子上的序列成员标记，所以同会话分叉、复制序列这类操作是对格子改标记，不搬数据。</p>',11)),(B(),r(p,null,{default:l(()=>[o(e,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GGUF%5B%22GGUF%20%E6%96%87%E4%BB%B6%EF%BC%9A%E5%85%83%E6%95%B0%E6%8D%AE%20%2B%20%E9%87%8F%E5%8C%96%E5%BC%A0%E9%87%8F%22%5D%20--%3E%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E5%AF%B9%E8%B1%A1%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20BATCH%5B%22%E6%89%B9%EF%BC%9Atoken%20%2B%20%E4%BD%8D%E7%BD%AE%20%2B%20%E5%BA%8F%E5%88%97%E5%8F%B7%22%5D%20--%3E%20CTX%5B%22%E4%BC%9A%E8%AF%9D%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20CTX%20--%3E%7C%E7%8E%B0%E5%9C%BA%E6%9E%84%E5%BB%BA%7C%20GRAPH%5B%22%E8%AE%A1%E7%AE%97%E5%9B%BE%EF%BC%88DAG%20%E8%8A%82%E7%82%B9%EF%BC%89%22%5D%0A%20%20GRAPH%20--%3E%20SCHED%5B%22%E5%90%8E%E7%AB%AF%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20SCHED%20--%3E%20CPU%5B%22CPU%20%E5%90%8E%E7%AB%AF%22%5D%0A%20%20SCHED%20--%3E%20GPU%5B%22Metal%20%2F%20CUDA%20%2F%20Vulkan%20%E5%90%8E%E7%AB%AF%22%5D%0A%20%20GPU%20--%3E%20KVC%5B%22KV%20%E7%BC%93%E5%AD%98%E6%A0%BC%E5%AD%90%EF%BC%9A%E4%BD%8D%E7%BD%AE%20%2B%20%E5%BA%8F%E5%88%97%E9%9B%86%E5%90%88%22%5D%0A%20%20CTX%20--%3E%20SAMPLER%5B%22%E9%87%87%E6%A0%B7%E5%99%A8%E9%93%BE%22%5D%20--%3E%7C%E4%B8%8B%E4%B8%80%E4%B8%AA%20token%7C%20BATCH%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"采样在 llama 里是一条可组合的链：贪心、温度、top-k、语法约束各是一个环节，逐级收窄候选集。语法约束作为采样环节挂在链上，这与引擎侧把文法做成逐步掩码是同一件事的两种挂法，见约束解码。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"运行时画图却不慢，原因是每步的图几乎相同：节点数是层数的线性函数，压图与分派是 CPU 上微秒级的函数表跳转，真正的毫秒花在 GPU 执行上。图当步建当步亡，会话状态全部住在缓存与采样器里，这使「多序列、分叉、续跑」只需正确维护格子标记。量化进存储类型，则省掉了运行期任何反量化调度——核直接按类型分派。单进程单机由此成立：没有跨进程的账要记，槽位表就是全部并发管理，服务示例里每个槽位一条序列，批是槽位的简单拼接。",-1)),(B(),r(p,null,{default:l(()=>[o(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20CELL%5B%22KV%20%E7%BC%93%E5%AD%98%EF%BC%9A%E4%B8%80%E6%8E%92%E6%A0%BC%E5%AD%90%22%5D%0A%20%20%20%20C1%5B%22%E6%A0%BC%E5%AD%90%200-9%EF%BC%9A%E5%BA%8F%E5%88%97%201%20%E4%B8%8E%E5%BA%8F%E5%88%97%202%20%E9%83%BD%E5%8F%AF%E8%A7%81%22%5D%20--%3E%20C2%5B%22%E6%A0%BC%E5%AD%90%2010-11%EF%BC%9A%E4%BB%85%E5%BA%8F%E5%88%97%201%20%E5%8F%AF%E8%A7%81%22%5D%0A%20%20end%0A%20%20B%5B%22%E4%BC%9A%E8%AF%9D%E8%AF%B7%E6%B1%82%EF%BC%9A%E5%BA%8F%E5%88%97%201%20%E5%9C%A8%E4%BD%8D%E7%BD%AE%2012%20%E5%88%86%E5%8F%89%E5%87%BA%E6%96%B0%E5%BA%8F%E5%88%97%203%22%5D%20--%3E%20OP%5B%22%E5%8F%AA%E6%94%B9%E6%A0%87%E8%AE%B0%EF%BC%9A%E6%A0%BC%E5%AD%90%200-11%20%E5%8A%A0%E4%B8%8A%E5%BA%8F%E5%88%97%203%20%E5%8F%AF%E8%A7%81%22%5D%0A%20%20OP%20--%3E%20W%5B%22%E6%96%B0%20token%20%E4%BB%8E%E6%A0%BC%E5%AD%90%2012%20%E8%B5%B7%E5%86%99%EF%BC%8C%E4%B8%8D%E5%A4%8D%E5%88%B6%E3%80%81%E4%B8%8D%E6%90%AC%E4%BB%BB%E4%BD%95%E5%8E%86%E5%8F%B2%20KV%22%5D%0A%20%20W%20--%3E%20M%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%8C%89%E5%BA%8F%E5%88%97%E6%88%90%E5%91%98%E6%8E%A9%E7%A0%81%E8%AF%BB%E6%A0%BC%E5%AD%90%EF%BC%9A%E5%BA%8F%E5%88%97%202%20%E4%BB%8D%E7%9C%8B%E4%B8%8D%E8%A7%81%E6%A0%BC%E5%AD%90%2010-11%22%5D%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有迭代级批调度与抢占：槽位一旦占用，整批同进同出，多租户语义不能与 vLLM 对表。跨后端的图切分在异构设备上仍是短板，某些算子会整体落回 CPU。缓存与批的 API 近年重写过，具体结构名以仓库当时状态为准。它不是集群服务的替代品，本课只回答「单机一笔账怎么记」。服务端组批、抢占与多租户的对照留到下一单元。</p><p><span class="marginnote">直觉类比「槽位表」：像餐馆只设 8 张固定桌，来客入座、吃完离座，桌号就是全部管理。没有「等位叫号重新分配」这一层——这是它与 vLLM 那种翻台率至上的引擎最直观的差别，也是它把复杂度留在「一家子用」而做不进「大堂满客」场景的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>llama.cpp 是两个库叠放：ggml 管张量、后端与计算图，llama 管模型、词表、缓存与采样。</li><li>每步现场构建 DAG，后端调度器把节点切给设备；建图成本相对 GPU 执行可忽略。</li><li>量化是张量存储类型，不是运行期转换层；四比特族直接参与核分派。</li><li>KV 缓存靠格子上的序列成员标记支持分叉与多序列，不靠连续数组假设。</li><li>单进程、槽位即并发，没有迭代级调度；结构名随版本漂移，以仓库当时状态为准。</li><li>出处：ggerganov/ggml 与 ggml-org/llama.cpp 仓库、GGUF 规范，按源码结构整理。</li></ul>',5))])}const f=n(m,[["render",C]]);export{u as __pageData,f as default};
